/* ============================================================
   PATCH v1.3.1 — ФИНАЛЬНЫЙ ФИКС
   ============================================================ */
(function(){
    if (window.__trkFinalV131) return;
    window.__trkFinalV131 = true;

    /* 1. ПЕРЕОПРЕДЕЛЯЕМ КЛИКИ В СВОДЕ (только для ячеек с задачей) */
    // Перехватываем клики на глобальном уровне, но только внутри #sumWrap
    document.addEventListener('click', function(e) {
        var td = e.target.closest('#sumWrap td.day-cell');
        if (!td) return;

        var taskId = td.getAttribute('data-task');
        var empId = td.getAttribute('data-emp');
        var dateStr = td.getAttribute('data-date');

        // Если ячейка пустая или это свёрнутый вид — не трогаем
        if (!taskId || taskId === '__collapsed__') return;

        // Если это отпуск/больничный (нет задачи, но есть эмплой) - открываем день сотрудника
        if (!taskId && empId && td.hasAttribute('data-absence')) {
            e.preventDefault();
            e.stopImmediatePropagation();
            if (typeof window.__trkOpenEmpDayModal === 'function') {
                window.__trkOpenEmpDayModal(empId, dateStr);
            }
            return;
        }

        // Если это задача — открываем карточку задачи!
        if (taskId) {
            e.preventDefault();
            e.stopImmediatePropagation();
            if (typeof window.__trkOpenTaskCardModal === 'function') {
                window.__trkOpenTaskCardModal(taskId);
            }
        }
    }, true); // true = capture phase, перебиваем старые onclick


    /* 2. ГИПОТЕЗЫ: ПРИНУДИТЕЛЬНО В GRID ПРИ ОТКРЫТИИ */
    if (typeof window.__trkOpenTaskModal === 'function' && !window.__trkOpenTaskModal._hypFix) {
        var origOpen = window.__trkOpenTaskModal;
        window.__trkOpenTaskModal = function(t) {
            var r = origOpen.apply(this, arguments);
            setTimeout(function() {
                var modal = document.getElementById('taskModal');
                if (!modal || !modal.classList.contains('active')) return;

                var hyp = document.getElementById('hypTreeGroup');
                var grid = modal.querySelector('.task-modal-grid');
                if (!hyp || !grid) return;

                // Возвращаем в grid (если кто-то утащил)
                if (hyp.parentNode !== grid) {
                    grid.appendChild(hyp);
                }

                // Делаем на всю ширину
                hyp.classList.add('trk-hyp-fullwidth');

                // Показываем, если задача сохранена (есть ID)
                var tid = document.getElementById('task_id');
                if (tid && tid.value) {
                    hyp.hidden = false;
                    hyp.style.display = 'block';
                } else {
                    hyp.hidden = true;
                    hyp.style.display = 'none';
                }
            }, 100);
            return r;
        };
        window.__trkOpenTaskModal._hypFix = true;
    }

    /* 3. ВОССТАНАВЛИВАЕМ ПЕРЕКЛЮЧАТЕЛИ В КАЛЕНДАРЕ */
    var style = document.createElement('style');
    style.textContent = `
        /* Переключатели в календаре должны быть видны */
        #dayModal #dayViewMode,
        #dayModal #dayColsPicker {
            display: inline-flex !important;
            visibility: visible !important;
        }

        /* Гипотезы на всю ширину */
        #taskModal .trk-hyp-fullwidth {
            grid-column: 1 / -1 !important;
            width: 100% !important;
            margin-top: 12px !important;
            padding: 12px 14px !important;
            box-sizing: border-box !important;
            display: block !important;
            background: var(--trk-hover-row, rgba(255,255,255,0.03)) !important;
            border: 1px solid var(--trk-card-border, rgba(245,215,110,0.18)) !important;
            border-radius: 12px !important;
        }

        /* Сетка для гипотез */
        #taskModal #hypTreeList {
            display: grid !important;
            grid-template-columns: repeat(auto-fit, minmax(360px, 1fr)) !important;
            gap: 10px !important;
        }

        /* Дыра в карточке задачи */
        #taskModal #taskAssigneesList {
            max-height: 220px !important;
        }
    `;
    document.head.appendChild(style);

})();
